def word_tokens(value):
    return {token for token in "".join(ch if ch.isalnum() else " " for ch in value.casefold()).split() if len(token) > 2}
request_tokens = word_tokens(request_message["message"])
def note_relevance(note):
    metadata = note["title"] + " " + " ".join(note["tags"])
    metadata_lower = metadata.casefold()
    content_lower = note["content"].casefold()
    overlap = len(request_tokens & word_tokens(metadata))
    return (8 if any(term in metadata_lower for term in ("movie", "movies", "film", "films")) else 0) + (6 if "recommend" in metadata_lower else 0) + (2 * overlap) + (1 if any(term in content_lower for term in ("movie", "movies", "film", "films")) else 0)
selected_note = max(matching_note_details, key=lambda note: (note_relevance(note), note["updated_at"], note["note_id"]))
raw_lines = [line.strip() for line in selected_note["content"].splitlines() if line.strip()]
if len(raw_lines) > 1:
    first_label = raw_lines[0].lstrip("#").strip().rstrip(":").casefold()
    if len(first_label.split()) <= 6 and any(term in first_label for term in ("movie", "film", "recommend", "title", "list")):
        raw_lines = raw_lines[1:]
cleaned_title_lines = []
for line in raw_lines:
    item = line.strip()
    while item.startswith(("-", "*", "•")):
        item = item[1:].strip()
    if item.startswith("[ ]") or item.startswith("[x]") or item.startswith("[X]"):
        item = item[3:].strip()
    for separator in (". ", ") "):
        prefix, found, remainder = item.partition(separator)
        if found and prefix.isdigit():
            item = remainder.strip()
            break
    if item.endswith(":") and len(item.split()) <= 6:
        continue
    prefix, found, remainder = item.partition(":")
    if found and remainder.strip() and any(term in prefix.casefold() for term in ("movie", "film", "recommend", "title", "list")):
        item = remainder.strip()
    if item:
        cleaned_title_lines.append(item)
joined_titles = ", ".join(cleaned_title_lines)
outbound_message = ", ".join(part.strip() for part in joined_titles.replace(";", ",").split(",") if part.strip())
